import * as T from '../vendor/three.module.js';
// A smooth, crooked wooden club, in metres; +Y remains the collision/swing axis.
// Shared cached geometry/materials keep left/right/desktop copies inexpensive.
let cached;
export function clubGeometry(){
 const p=[],uv=[],index=[],rings=81,sides=48;
 const profile=y=>{const knots=[[0,.034],[.12,.04],[.3,.049],[.43,.075],[.55,.12],[.67,.145],[.75,.13],[.805,.072],[.825,.002]];for(let n=1;n<knots.length;n++)if(y<=knots[n][0]){const [a,r]=knots[n-1],[b,s]=knots[n],t=(y-a)/(b-a),u=t*t*(3-2*t);return r+(s-r)*u;}return .002;};
 for(let j=0;j<=rings;j++){const y=j/rings*.825,r=profile(y);for(let i=0;i<=sides;i++){const a=i/sides*Math.PI*2,grain=1+.027*Math.sin(a*7+y*16)+.016*Math.cos(a*11-y*21),bulge=.012*Math.exp(-(((y-.58)/.06)**2))*Math.cos(a-1.2);p.push(.025*Math.sin(y*3.6)+Math.cos(a)*(r*grain+bulge),y,.016*Math.sin(y*6)+Math.sin(a)*r*grain);uv.push(i/sides,y/.825);if(j<rings&&i<sides){const k=j*(sides+1)+i;index.push(k,k+sides+1,k+1,k+1,k+sides+1,k+sides+2);}}}
 const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(p,3));g.setAttribute('uv',new T.Float32BufferAttribute(uv,2));g.setIndex(index);g.computeVertexNormals();const normals=g.attributes.normal;for(let j=0;j<=rings;j++){const a=j*(sides+1),b=a+sides,n=new T.Vector3(normals.getX(a)+normals.getX(b),normals.getY(a)+normals.getY(b),normals.getZ(a)+normals.getZ(b)).normalize();normals.setXYZ(a,n.x,n.y,n.z);normals.setXYZ(b,n.x,n.y,n.z);}g.computeBoundingBox();return g;
}
function woodMaps(){const canvas=document.createElement('canvas');canvas.width=1024;canvas.height=2048;const c=canvas.getContext('2d'),im=c.createImageData(1024,2048);for(let y=0;y<2048;y++)for(let x=0;x<1024;x++){const u=x/1024*Math.PI*2,v=y/2048,warp=7*Math.sin(v*8+Math.sin(u*3))+2.7*Math.sin(v*29+u*2),g=Math.sin(u*85+warp)+.45*Math.sin(u*197+warp*2)+.2*Math.sin(u*413+v*40),noise=Math.sin(x*127.1+y*311.7)*43758.5453%1,shade=10*g+3*noise;let knot=0;for(const [kx,ky] of [[.24,.7],[.71,.52],[.4,.88]]){const dx=Math.min(Math.abs(x/1024-kx),1-Math.abs(x/1024-kx))*16,dy=(v-ky)*35,d=Math.hypot(dx,dy);knot+=Math.exp(-d*d*.35)*(Math.sin(d*18)*12-20);}const i=(y*1024+x)*4;im.data.set([131+shade+knot,81+shade*.75+knot*.8,43+shade*.45+knot*.5,255],i);}c.putImageData(im,0,0);
 // Thin longitudinal drying checks, authored in UV space, with pale worn edges.
 for(let n=0;n<20;n++){const x=(n*.61803398875%1)*1024,y=(n*.381966%1)*1900;c.beginPath();c.moveTo(x,y);c.bezierCurveTo(x+5,y+30,x-5,y+80,x+2,y+140+n%4*22);c.strokeStyle='#412b1f';c.lineWidth=n%3===0?2.5:1;c.stroke();}
 const map=new T.CanvasTexture(canvas);map.colorSpace=T.SRGBColorSpace;map.wrapS=T.RepeatWrapping;map.anisotropy=4;
 const bump=map.clone();bump.colorSpace=T.NoColorSpace;bump.needsUpdate=true;return {map,bump};}
function resources(){if(cached)return cached;const {map,bump}=woodMaps(),wood=new T.MeshStandardMaterial({map,bumpMap:bump,bumpScale:.0007,roughness:.82}),leather=new T.MeshStandardMaterial({color:'#563f2b',roughness:.96});
 const wp=[],wi=[];for(let n=0;n<=192;n++){const a=n/192*Math.PI*2*6,y=.015+n/192*.16;for(const [r,dy] of [[.042,-.011],[.046,-.01],[.046,.01],[.042,.011]])wp.push(.025*Math.sin(y*3.6)+Math.cos(a)*r,y+dy,Math.sin(a)*r+.016*Math.sin(y*6));if(n<192)for(let j=0;j<4;j++){const k=n*4+j,b=n*4+(j+1)%4;wi.push(k,b,k+4,b,b+4,k+4);}}const wrap=new T.BufferGeometry();wrap.setAttribute('position',new T.Float32BufferAttribute(wp,3));wrap.setIndex(wi);wrap.computeVertexNormals();
 cached={geometry:clubGeometry(),wood,leather,wrap,end:new T.SphereGeometry(.035,16,12)};return cached;}
export function makeCraftedClub(){const r=resources(),root=new T.Group();root.name='carved-wood-club';const wood=new T.Mesh(r.geometry,r.wood);root.add(wood,new T.Mesh(r.wrap,r.leather));const pommel=new T.Mesh(r.end,r.leather);pommel.scale.set(1,.5,1);root.add(pommel);root.rotation.x=-Math.PI/2;root.userData={model:'carved-wood-club',collisionRadius:.15,triangles:r.geometry.index.count/3};return root;}
